import csv
rows = list(csv.DictReader(open('/app/climate_analyzer/sample_data/climate_data.csv')))
sums, counts = {}, {}
for r in rows:
    s, v = r['station'], float(r['temp_c'])
    sums[s] = sums.get(s, 0.0) + v
    counts[s] = counts.get(s, 0) + 1
for s in ('101', '102'):
    mean = sums[s] / counts[s]
    print(f"Station {s} mean temperature: {mean:.2f} C")

